<script setup lang="ts">
import { Head, useForm } from '@inertiajs/vue3';
import InternalLayout from '@/Layouts/InternalLayout.vue';
import BusinessTypeEditor, { type BusinessType } from '@/Components/Business/BusinessTypeEditor.vue';
import { useBusinessCopy } from '@/localization/business';
defineProps<{ types: BusinessType[]; providers: { key: string; label: string }[]; products: { key: string; provider: string; label_ar: string; label_en: string }[]; canManage: boolean }>();
const { locale } = useBusinessCopy();
const c = (ar: string, en: string) => locale.value === 'ar' ? ar : en;
const form = useForm({ key: '', name_ar: '', name_en: '', active: true });
function create() { form.post(route('internal.business-types.store'), { preserveScroll: true, onSuccess: () => form.reset() }); }
</script>
<template><Head :title="c('أنواع الأنشطة', 'Business types')" /><InternalLayout><template #header><h1>{{ c('أنواع الأنشطة', 'Business types') }}</h1><p>{{ c('تعريف السياق وتوجيه المصادر ومراجعة الاعتبارات الأولية.', 'Define context, guide sources, and review initial promotion priors.') }}</p></template><div class="business-catalog"><p v-if="!canManage" class="catalog-note">{{ c('عرض فقط. تعديل الأنواع يحتاج إلى منحة إدارة صريحة.', 'Read only. Editing types requires an explicit management grant.') }}</p><details v-if="canManage" class="catalog-create"><summary>{{ c('إضافة نوع نشاط', 'Add a business type') }}</summary><form class="catalog-form" @submit.prevent="create"><label>{{ c('المفتاح الثابت', 'Stable key') }}<input v-model="form.key" required dir="ltr" /></label><label>{{ c('الاسم بالعربية', 'Arabic name') }}<input v-model="form.name_ar" required dir="rtl" /></label><label>{{ c('الاسم بالإنجليزية', 'English name') }}<input v-model="form.name_en" required dir="ltr" /></label><label class="catalog-check"><input v-model="form.active" type="checkbox" />{{ c('متاح للاختيار', 'Available for selection') }}</label><p v-for="(message, field) in form.errors" :key="field" role="alert" class="catalog-error">{{ message }}</p><p v-if="form.recentlySuccessful" role="status">{{ c('أُضيف النوع.', 'Type added.') }}</p><button :disabled="form.processing">{{ form.processing ? c('جارٍ الحفظ…', 'Saving…') : c('إضافة النوع', 'Add type') }}</button></form></details><p v-if="!types.length" class="catalog-note">{{ c('لا توجد أنواع أنشطة بعد.', 'No business types yet.') }}</p><BusinessTypeEditor v-for="type in types" :key="type.id" :type="type" :providers="providers" :products="products" :can-manage="canManage" /></div></InternalLayout></template>
